// block_graphical_events/chart_module.js
define(['core/toast','chart'], function(addToast,Chart) {
    return {
        init: function(data) {
            
            createPieChart(data);
        }
    };
});




const createPieChart=(data)=>{
  //Grafica que muestra el número de tickets (abiertos, cerrados, erroneos y asignados) por dotación
  const ctx = document.getElementById('myPieChart');
            
  
  // Create the chart
  new Chart(ctx, {
      type: 'pie',
      data: {
          labels: ['Fails','Others'],
          datasets: [
                {
                  label: ['Failed','Others'],
                  data: [20,80],
                  backgroundColor: [
                    'rgba(120, 99, 255, 0.4)',
                   'rgba(0, 99, 255, 0.4)',
                    ],
                 
                },
                
                
          ]
      },
      options: {
        responsive: true,
        plugins: {
          legend: {
            position: 'top',
          },
          title: {
            display: true,
            text: 'Percentage of failed tickets'
          }
        }
      },
  });
}

